/// Запускает компилятор C в потоке с огромным стеком. Огромный -- потому что страшно.
fn compile_c_big(src: Vec<u8>) -> Result<String, String> {
    std::thread::Builder::new().stack_size(512 * 1024 * 1024).spawn(move || compile_c(&src)).unwrap().join().unwrap()
}

fn lua_main(path: &str) -> i32 {
    let src = read_file(path);
    let mut it = lua::Interp::new();
    match it.run(&src, path) {
        Ok(_) => 0,
        Err(e) => {
            let msg = match it.tostr(&e) {
                Ok(m) => String::from_utf8_lossy(&m).to_string(),
                Err(_) => "?".to_string(),
            };
            writeln!(std::io::stderr(), "lua: {}", msg).unwrap();
            1
        }
    }
}

/// Превращает шестнадцатеричный текст обратно в байты. Пробелы и переносы игнорирует из вежливости.
fn hex_decode(s: &str) -> Vec<u8> {
    let digits: Vec<u8> = s.bytes().filter(|b| (*b as char).is_ascii_hexdigit()).collect();
    let mut out = Vec::with_capacity(digits.len() / 2);
    let val = |c: u8| -> u8 { (c as char).to_digit(16).unwrap() as u8 };
    let mut i = 0;
    while i + 1 < digits.len() {
        out.push(val(digits[i]) * 16 + val(digits[i + 1]));
        i += 2;
    }
    out
}

fn read_file(path: &str) -> Vec<u8> {
    let mut v = Vec::new();
    std::io::Read::read_to_end(&mut std::fs::File::open(path).unwrap(), &mut v).unwrap();
    v
}

fn main() {
    // прогреваем бесполезности, чтобы потом не было стыдно
    let _ = bubble::run_all();
    let args: Vec<String> = std::env::args().collect();

    if let Some(i) = args.iter().position(|a| a == "--pack") {
        let text = String::from_utf8(read_file(&args[i + 1])).unwrap();
        let snd: Vec<u8> = match args.get(i + 3) {
            Some(p) if !p.starts_with("--") => read_file(p),
            _ => Vec::new(),
        };
        let out = match pack::pack(&text, &snd) {
            Ok(o) => o,
            Err(e) => {
                writeln!(std::io::stderr(), "упаковщик сломался: {}", e).unwrap();
                std::process::exit(1);
            }
        };
        std::fs::File::create(&args[i + 2])
            .unwrap()
            .write_all(&out)
            .unwrap();
        writeln!(std::io::stderr(), "упаковано: {} байт", out.len()).unwrap();
        return;
    }

    if let Some(i) = args.iter().position(|a| a == "--lua") {
        let path = args[i + 1].clone();
        let h = std::thread::Builder::new().stack_size(512 * 1024 * 1024).spawn(move || lua_main(&path)).unwrap();
        std::process::exit(h.join().unwrap());
    }

    let c_at = args.iter().position(|a| a == "--c");
    let cc_at = args.iter().position(|a| a == "--cc-asm");
    let c_path_of = |i: usize| -> Option<String> {
        match args.get(i + 1) {
            Some(p) if !p.starts_with("--") => Some(p.clone()),
            _ => None,
        }
    };
    let mut c_asm: Option<String> = None;
    if let Some(i) = c_at.or(cc_at) {
        let csrc: Vec<u8> = match c_path_of(i) {
            Some(p) => read_file(&p),
            None => HELLO_C.as_bytes().to_vec(),
        };
        match compile_c_big(csrc) {
            Ok(a) => c_asm = Some(a),
            Err(e) => {
                writeln!(std::io::stderr(), "компилятор C: {}", e).unwrap();
                std::process::exit(1);
            }
        }
        if cc_at.is_some() {
            print!("{}", c_asm.unwrap());
            return;
        }
    }

    if args.iter().any(|a| a == "--quine") {
        let h = std::thread::Builder::new().stack_size(512 * 1024 * 1024).spawn(quine_main).unwrap();
        std::process::exit(h.join().unwrap());
    }

    let selftest = args.iter().any(|a| a == "--selftest");
    let play_at = args.iter().position(|a| a == "--play");
    let play = play_at.is_some();
    let from_file: Option<String> = match args.iter().position(|a| a == "--asm") {
        Some(i) => Some(String::from_utf8(read_file(&args[i + 1])).unwrap()),
        None => None,
    };
    let source: &str = match from_file {
        Some(ref t) => &t[..],
        None => {
            if let Some(ref a) = c_asm {
                &a[..]
            } else if play {
                PLAYER
            } else if selftest {
                SELFTEST
            } else {
                HELLO
            }
        }
    };
    let delay: u64 = match std::env::var("HELLO_DELAY_MS") {
        Ok(s) => s.parse().unwrap_or(40),
        Err(_) => 40,
    };
    let fps: u64 = match std::env::var("HELLO_FPS") {
        Ok(s) => s.parse().unwrap_or(15),
        Err(_) => 15,
    };
    let image = match asm::assemble(source) {
        Ok(i) => i,
        Err(e) => {
            writeln!(std::io::stderr(), "assembler error: {}", e).unwrap();
            std::process::exit(1);
        }
    };
    let mut bus = bus::Bus::new(delay);
    bus.load();
    bus.reset(&image);
    bus.set_fps(fps);
    if let Some(i) = play_at {
        bus.open_audio();
        let disk: Vec<u8> = match args.get(i + 1) {
            Some(p) if !p.starts_with("--") => read_file(p),
            _ => match pack::pack(video_data::ASC, &hex_decode(video_data::SND_HEX)) {
                Ok(d) => d,
                Err(e) => {
                    writeln!(std::io::stderr(), "вшитое видео сломалось: {}", e).unwrap();
                    std::process::exit(1);
                }
            },
        };
        bus.attach_disk(disk);
    }
    let limit: u64 = if play { std::u64::MAX } else { 10_000_000 };
    let mut cpu = cpu::Cpu::new();
    while !cpu.halted && cpu.cycles < limit {
        cpu.step(&mut bus);
    }
    bus.finish();
    writeln!(
        std::io::stderr(),
        "[halted after {} cycles, {} bus clocks, {} bytes sent, {} frames]",
        cpu.cycles,
        bus.clock,
        bus.uart.sent,
        bus.video.frames
    )
    .unwrap();
}

#[cfg(test)]
mod alu_tests {
    use alu;
    use word::Word;

    #[test]
    fn mul_div_mod_match_native() {
        let xs = [
            0u16, 1, 2, 3, 7, 10, 100, 255, 1000, 32767, 32768, 40000, 65535,
        ];
        for a in xs.iter() {
            for b in xs.iter() {
                let (wa, wb) = (Word::from_u16(*a), Word::from_u16(*b));
                assert_eq!(alu::mul(wa, wb).to_u16(), a.wrapping_mul(*b));
                if *b != 0 {
                    let (q, r) = alu::divmod(wa, wb);
                    assert_eq!(q.to_u16(), a / b);
                    assert_eq!(r.to_u16(), a % b);
                }
                let (_, ge) = alu::sub_flags(wa, wb);
                assert_eq!(ge, a >= b);
            }
        }
    }
}

#[cfg(test)]
mod lua_tests {
    use asm;
    use bus;
    use cpu;
    use lua;

    fn run_big<F: FnOnce() + Send + 'static>(f: F) {
        std::thread::Builder::new().stack_size(256 * 1024 * 1024).spawn(f).unwrap().join().unwrap();
    }

    fn eval(src: &str) -> lua::Val {
        let mut it = lua::Interp::new();
        let r = it.run(src.as_bytes(), "t").ok().unwrap();
        r.into_iter().next().unwrap_or(lua::Val::Nil)
    }

    fn num(v: lua::Val) -> f64 {
        match v {
            lua::Val::Num(n) => n,
            _ => panic!("не число"),
        }
    }

    fn text(v: lua::Val) -> String {
        match v {
            lua::Val::Str(s) => String::from_utf8_lossy(&s).to_string(),
            _ => panic!("не строка"),
        }
    }

    #[test]
    fn lua_arithmetic_and_closures() {
        run_big(|| {
            assert_eq!(num(eval("return 1 + 2 * 3")), 7.0);
            assert_eq!(num(eval("return 2 ^ 10 + 7 // 2 + -7 % 3")), 1029.0);
            assert_eq!(num(eval("local function f(n) if n < 2 then return n end return f(n-1) + f(n-2) end return f(15)")), 610.0);
            assert_eq!(num(eval("local fs = {} for i = 1, 3 do fs[i] = function() return i end end return fs[1]() * 100 + fs[3]()")), 103.0);
            assert_eq!(num(eval("local t = setmetatable({}, {__index = function(t, k) return k * 2 end}) return t[21]")), 42.0);
        });
    }

    #[test]
    fn lua_strings_and_patterns() {
        run_big(|| {
            assert_eq!(text(eval("return string.format('%5.2f|%-4d|%04x', 3.14159, 7, 255)")), " 3.14|7   |00ff");
            assert_eq!(text(eval("return (string.gsub('hello world', '(%w+)', string.upper))")), "HELLO WORLD");
            assert_eq!(text(eval("local k, v = string.match('key=value', '(%w+)=(%w+)') return v .. k")), "valuekey");
            assert_eq!(text(eval("local r = {} for w in string.gmatch('a bb ccc', '%a+') do r[#r + 1] = #w end return table.concat(r, ',')")), "1,2,3");
            assert_eq!(text(eval("local ok, e = pcall(function() error('x', 0) end) return tostring(ok) .. e")), "falsex");
        });
    }

    #[test]
    fn c_through_lua_prints_hello_on_the_emulator() {
        run_big(|| {
            let asm_text = ::compile_c(::HELLO_C.as_bytes()).ok().unwrap();
            let image = asm::assemble(&asm_text).ok().unwrap();
            let mut bus = bus::Bus::new(0);
            bus.load();
            bus.reset(&image);
            let mut cpu = cpu::Cpu::new();
            while !cpu.halted && cpu.cycles < 5_000_000 {
                cpu.step(&mut bus);
            }
            assert!(cpu.halted);
            assert_eq!(bus.uart.sent, 68);
        });
    }
}

